urlset:
{% set static_pages = [
    '/',
    '/about-us',
    '/contacts',
    '/payment',
    '/refund-policy',
    '/offer',
    '/tos',
    '/privacy-policy',
    '/signup',
    '/login'
] %}
{% for page in static_pages %}

    {{ page|link }}
    {% if page == '/' %}1.0{% else %}0.8{% endif %}
    monthly

{% endfor %}

{# products #}
{% for i, product in guest.product_get_list({"per_page": 50}).list %}

    {{ 'order'|link }}/{{product.slug}}
    {{product.updated_at|date('Y-m-d')}}
    0.9
    weekly

{% endfor %}

{# knowledge base items #}
{% if guest.support_kb_enabled() %}
{% for i, article in guest.support_kb_article_get_list({"per_page":50}).list %}

    {{ 'support/kb'|link }}/{{article.category.slug}}/{{article.slug}}
    {{article.updated_at|date('Y-m-d')}}
    0.9
    weekly

{% endfor %}
{% endif %}
